import hashlib,json,subprocess,urllib.request
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parents[2];source=json.loads((P/'incoming-source.json').read_text());changed=[name for name,sha in source.items() if not (R/name).is_file() or hashlib.sha256((R/name).read_bytes()).hexdigest()!=sha];assert changed==[],changed
snap=json.loads((P/'snapshot.json').read_text());assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=R).decode().strip()==snap['HEAD'];assert subprocess.check_output(['git','branch','--show-current'],cwd=R).decode().strip()==snap['branch'];assert '\nactive_run: NONE\n' in (R/'docs/task33/implementation-status.md').read_text()
a=json.loads((P/'recheck.result.json').read_text());assert not a.get('error') and not a['errors'] and not a['network'];assert len(a['rows'])==8 and sum(x['status']=='FAIL' for x in a['rows'])==2
probe=json.loads((P/'probe.json').read_text());assert probe['transaction']=='READ ONLY' and probe['candidate_status']=='pending' and probe['payload_fields']==['name_en'];assert probe['active_group_price']=='20.00' and probe['direct_place_tariffs']==0 and probe['form_valid'] and not probe['is_ready'];assert probe['issues']==[{'code':'price','field':'pricing_plans'}] and probe['cleaned_nested_pricing'] is None;assert probe['simulated_form_valid'] and probe['simulated_is_ready'] and not probe['simulated_issues'];assert probe['live_name_en']!='Fictional partial name OFFER09'
sv=json.loads((P/'server.json').read_text());assert str(P/'runtime.py').encode() in (Path('/proc')/str(sv['pid'])/'cmdline').read_bytes();runtime=json.load(urllib.request.urlopen(sv['url']+'/qa/start-version/',timeout=10));assert runtime['testing'] and runtime['entry_matches_startup'] and runtime['startup_matches_disk'];(P/'runtime-final.json').write_text(json.dumps(runtime,indent=2))
for n in ['server','read-only-probe']:assert json.loads((P/(n+'.command.json')).read_text())['exit']==0
q=subprocess.run(['git','diff','--check'],cwd=R,capture_output=True,text=True);assert q.returncode==0,q.stdout+q.stderr
png=[{'file':'screenshots/'+f.name,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()} for f in sorted((P/'screenshots').glob('*.png'))];assert len(png)==3;(P/'png-manifest.json').write_text(json.dumps(png,indent=2));(P/'worktree-final.txt').write_text(subprocess.check_output(['git','status','--short'],cwd=R).decode())
v={'id':'OFFER-QA-09','status':'CONFIRMED OPEN; two-file PLAN awaits approval','application_source_changes':changed,'snapshot_preserved':True,'runtime_source_match':True,'native_checks':8,'prerequisite_PASS':6,'reproduced_FAIL':2,'PNG':len(png),'read_only_actual_price_missing':'CONFIRMED','simulation':'In-memory trusted tree injection resolves readiness; diagnostic only, NOT application acceptance','backend_regression_tests':'NOT RUN; PLAN ONLY','full_ACCEPT05':'NOT RUN','global':'NOT RUN','external':'BLOCKED / NOT RUN','production':'NOT RUN'};(P/'verification.json').write_text(json.dumps(v,indent=2));print(json.dumps(v))
